values ('dialog_fq_conc_090', 'fq_conc_090', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. The World Engine is online", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 10x Aethel Abyssal Reaver; Defeat 2x Crystal Tyrant; Collect 1x Raw Aethel Fragment\n\nComplete and report back.\n\nRewards: 13000 EXP · 6500 Currency · 3250 CRD · 4200 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 120)
