values ('dialog_fq_conc_093', 'fq_conc_093', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Crystal Tyrants have made their final stand in the Shattered Heart", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 3x Crystal Tyrant; Defeat 1x Ashen Drake\n\nComplete and report back.\n\nRewards: 12000 EXP · 6000 Currency · 3000 CRD · 4000 Reputation · Quantum Distortion Stone", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 123)
