values ('dialog_fq_conc_097', 'fq_conc_097', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. The Final Seal — The World Engine requires one final calibration", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Gigantic Jotunn; Defeat 1x Abyss Harbinger; Collect 3x Materials\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 15000 EXP · 7500 Currency · 3750 CRD · 5000 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 127)
