values ('dialog_fq_conc_100', 'fq_conc_100', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. You have done the impossible", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to NEXUS_CORE; Speak with npc_concordium_officer\n\nReturn when it''s done. The Concordium keeps score.\n\nRewards: 50000 EXP · 25000 Currency · 12500 CRD · 10000 Reputation · Resonanted Astral Phase Crystal + Eternal Crown", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 130)
