insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_014', 'fq_arc_014', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Perfect timing. I have a hypothesis to test. Archivist Sylas has mapped the echo patterns in the deepest cavern chambers...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard isn''t just a power source — it''s a fragment of Aethelgardian consciousness, a library encoded in energy. Every creature affected carries a piece. We collect them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your mission: Defeat 5x Resonance Bat; Collect 2x void_fragment\n\nThe Observatory will analyze whatever you recover.\n\nRewards: 380 EXP · 200 Currency · 200 Reputation · Memory Fragment Chip", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 144)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_015', 'fq_arc_015', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Ah, Scholar. What the Signal Hides — Something is actively corrupting the Aethelgardian signal in the Resonance ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Knowledge demands risk. The Concordium wants to regulate the Shard. The Hegemony wants to weaponize it. We want to understand it.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your mission: Defeat 3x Resonance Golem; Defeat 5x Resonance Bat\n\nThe Observatory will analyze whatever you recover.\n\nRewards: 500 EXP · 280 Currency · 300 Reputation · Core Fragment", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 145)
