values ('dialog_fq_arc_019', 'fq_arc_019', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Ah, Scholar. The Sum of Lost Knowledge — The Resonance Echo that formed in the deepest chamber is not a creature in ...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Your previous encounters generated extraordinary data. The resonance patterns suggest a deeper structure — a language waiting to be decoded.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Resonance Echo; Defeat 2x Resonance Golem\n\nBring back everything you can. The archives await.\n\nRewards: 800 EXP · 450 Currency · 225 CRD · 450 Reputation · Entropy Core + Con Medium Hp Cell", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 149)
