values ('dialog_fq_arc_058', 'fq_arc_058', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Scholar! The Observatory has been recording unusual patterns. The Abyss Harbinger is not just a monster", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Your previous encounters generated extraordinary data. The resonance patterns suggest a deeper structure — a language waiting to be decoded.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your mission: Defeat 6x Aethel Abyssal Reaver; Defeat 1x Chrono Wraith; Collect 1x Raw Aethel Fragment\n\nThe Observatory will analyze whatever you recover.\n\nRewards: 7500 EXP · 3800 Currency · 1900 CRD · 2400 Reputation · Event Horizon Fragment L", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 188)
