values ('dialog_fq_arc_067', 'fq_arc_067', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Ah, Scholar. Behemoth Siege — Corrupted Behemoths assault the Core''s primary conduits", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Your previous encounters generated extraordinary data. The resonance patterns suggest a deeper structure — a language waiting to be decoded.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 3x Aethel Corrupted Behemoth; Collect 1x Raw Aethel Fragment\n\nBring back everything you can. The archives await.\n\nRewards: 6200 EXP · 3100 Currency · 1550 CRD · 2000 Reputation · Corrupted Synapse Cluster", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 197)
