values ('dialog_fq_arc_070', 'fq_arc_070', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Scholar! The Observatory has been recording unusual patterns. THE GRAVITATIONAL TRIAL", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard isn''t just a power source — it''s a fragment of Aethelgardian consciousness, a library encoded in energy. Every creature affected carries a piece. We collect them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your mission: Defeat 1x Gravity Titan; Defeat 5x Aethel Abyssal Reaver; Collect 1x core_fragment\n\nThe Observatory will analyze whatever you recover.\n\nRewards: 20000 EXP · 10000 Currency · 5000 CRD · 7000 Reputation · Titan Core + Gravity Well Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 200)
