values ('dialog_fq_arc_083', 'fq_arc_083', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Perfect timing. I have a hypothesis to test. The city contains the Eternal Library", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Your previous encounters generated extraordinary data. The resonance patterns suggest a deeper structure — a language waiting to be decoded.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your mission: Collect 5x abyssal_reaver_claw; Defeat 4x Aethel Abyssal Reaver\n\nThe Observatory will analyze whatever you recover.\n\nRewards: 8800 EXP · 4400 Currency · 2200 CRD · 2800 Reputation · Memory Fragment Chip", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 213)
