values ('dialog_fq_arc_084', 'fq_arc_084', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Ah, Scholar. Apex Drake — The Ashen Drake has evolved to its Apex form", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard isn''t just a power source — it''s a fragment of Aethelgardian consciousness, a library encoded in energy. Every creature affected carries a piece. We collect them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your mission: Defeat 1x Ashen Drake; Collect 1x ancient_scale\n\nThe Observatory will analyze whatever you recover.\n\nRewards: 12000 EXP · 6000 Currency · 3000 CRD · 4000 Reputation · Drake Heart + Ancient Scale", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 214)
