values ('dialog_fq_arc_085', 'fq_arc_085', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Ah, Scholar. Apex Harbinger — The Abyss Harbinger''s rebirth brings new void-knowledge", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard isn''t just a power source — it''s a fragment of Aethelgardian consciousness, a library encoded in energy. Every creature affected carries a piece. We collect them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 1x Abyss Harbinger; Collect 1x void_core\n\nBring back everything you can. The archives await.\n\nRewards: 13000 EXP · 6500 Currency · 3250 CRD · 4200 Reputation · Void Core + Event Horizon Fragment L", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 215)
