values ('dialog_fq_arc_088', 'fq_arc_088', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Perfect timing. I have a hypothesis to test. The Aethel Siphon Core is now the Arcanum''s primary research facility", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Knowledge demands risk. The Concordium wants to regulate the Shard. The Hegemony wants to weaponize it. We want to understand it.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Travel to AETHEL_SIPHON_CORE; Collect 5x Raw Aethel Fragment\n\nBring back everything you can. The archives await.\n\nRewards: 10000 EXP · 5000 Currency · 2500 CRD · 3200 Reputation · Power Regulator Core", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 218)
