values ('dialog_fq_arc_099', 'fq_arc_099', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Scholar! The Observatory has been recording unusual patterns. The deepest Void Echo Chasm holds the final secret", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Knowledge demands risk. The Concordium wants to regulate the Shard. The Hegemony wants to weaponize it. We want to understand it.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your mission: Travel to VOID_ECHO_CHASM; Defeat 1x Gravity Titan; Defeat 1x Abyss Harbinger (+1 more)\n\nThe Observatory will analyze whatever you recover.\n\nRewards: 25000 EXP · 12000 Currency · 6000 CRD · 8000 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 229)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_100', 'fq_arc_100', 'npc_high_seeker_voss', 'greeting', '[{"id": "greeting", "text": "Perfect timing. I have a hypothesis to test. You have done the impossible", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Shard isn''t just a power source — it''s a fragment of Aethelgardian consciousness, a library encoded in energy. Every creature affected carries a piece. We collect them.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your mission: Travel to OBSERVATORY_SPIRE; Speak with npc_arcanum_scholar\n\nThe Observatory will analyze whatever you recover.\n\nRewards: 50000 EXP · 25000 Currency · 12500 CRD · 10000 Reputation · Resonanted Astral Phase Crystal + Sovereign Seal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 230)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_iron_001', 'fq_iron_001', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "War doesn''t wait, Soldier. The Iron Hegemony does not recruit", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Defeat 5x Broken Scout Drone; Collect 2x Collect salvage parts for the war machine.\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 50 EXP · 30 Currency · 30 Reputation · Con Small Hp Cell + Scrap Metal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 231)
