values ('dialog_fq_iron_005', 'fq_iron_005', 'npc_hegemony_class_trainer', 'greeting', '[{"id": "greeting", "text": "War doesn''t wait, Soldier. Warlord Harkon Steele reviews every conscript personally", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium thinks diplomacy solves everything. The Arcanum thinks reading books does. We know better. Strength is the only language this world understands.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Speak with npc_hegemony_class_trainer; Speak with class_change_screen; Defeat 3x Broken Scout Drone\n\nDon''t come back until it''s done. The Hegemony has no use for half-measures.\n\nRewards: 400 EXP · 200 Currency · 150 Reputation · Wpn Iron Sword + Arm Iron Plate", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 235)
