values ('dialog_fq_iron_006', 'fq_iron_006', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. The Ravine Is Ours Now — The Iron Ravine sits on mineral deposits that could supply the Bastion''s fo...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium thinks diplomacy solves everything. The Arcanum thinks reading books does. We know better. Strength is the only language this world understands.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Travel to IRON_RAVINE; Collect 1x Deploy a forward base beacon.\n\nStrength prevails.\n\nRewards: 100 EXP · 60 Currency · 60 Reputation · Mat Iron Ore", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 236)
