values ('dialog_fq_iron_008', 'fq_iron_008', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "Front and center, Soldier. A Lesson in Superior Force — An Iron Ravine Brute has claimed the central shaft as its territory and cru...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Scrap Fields don''t forgive weakness. Every soldier who''s made it this far knows. The real Hegemony soldiers separate themselves here.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 2x Iron Ravine Brute; Collect 1x Claim the Brute''s weapon as trophy.\n\nStrength prevails.\n\nRewards: 180 EXP · 100 Currency · 50 CRD · 100 Reputation · Rusted Plate", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 238)
