insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_iron_009', 'fq_iron_009', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "You''ve got that look — ready for something harder. A Scrapfield Enforcer", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A thousand recruits walked through the Bastion gates. A fraction lasted their first week. You''re still standing. Prove there''s more iron in your blood.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Your orders: Defeat 1x Scrapfield Enforcer; Defeat 1x Iron Ravine Sentinel\n\nStrength prevails.\n\nRewards: 250 EXP · 150 Currency · 75 CRD · 150 Reputation · Scrap Circuit", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 239)
